178	// handleIgnoreSecret prompts confirmation to ignore a secret finding
179	func (m *Model) handleIgnoreSecret() {
180		finding, ok := m.findingsTable.Selected()
181		if m.activeTab != TabSecrets || !ok {
182			return
183		}
184		m.findingToIgnore = &finding
185		m.confirmModal = sharedcomponents.NewConfirmModal(
186			"Ignore Secret",
187			fmt.Sprintf("Add this secret to .gitleaksignore?\n\nFile: %s\nRule: %s", finding.File, finding.ID),
188		)
