	if err != nil {
		t.Fatalf("enter could not read the result the rescan stored: %v", err)
	}
	if len(stored.Findings) != len(result.Findings) {
		t.Errorf("%d findings stored, want %d", len(stored.Findings), len(result.Findings))
	}
}

