93	// recorder collects progress from the scan goroutines.
94	type recorder struct {
95		mu      sync.Mutex
96		updates []ProgressUpdate
97	}
98	
99	func (rec *recorder) fn() func(ProgressUpdate) {
100		return func(u ProgressUpdate) {
101			rec.mu.Lock()
102			defer rec.mu.Unlock()
103			rec.updates = append(rec.updates, u)
104		}
105	}
106	
107	// statusOf returns the transitions reported for one stage, in order. A running
108	// update carrying a detail is the tool talking, not a transition, so it is left
109	// out — otherwise every line of a database download would read as a state
110	// change.
111	func (rec *recorder) statusOf(stage string) []StageStatus {
112		rec.mu.Lock()
113		defer rec.mu.Unlock()
114		var out []StageStatus
115		for _, u := range rec.updates {
116			if u.Stage != stage || (u.Status == StageRunning && u.Detail != "") {
117				continue
118			}
119			out = append(out, u.Status)
120		}
121		return out
122	}
